(3999085, 571693, 23002, '<td valign="top">here kitty kitty...</td>', 'here kitty kitty...', '2007-08-15 01:44:05.000000', NULL, 1),
(3999094, 571308, 81365, '<td valign="top">nice view, and I actually like how the bridge is framing the corner of the picture.  But the light flare is a bit distracting in the upper corner.</td>', 'nice view, and I actually like how the bridge is framing the corner of the picture.  But the light flare is a bit distracting in the upper corner.', '2007-08-15 01:46:00.000000', NULL, 1),
(3999096, 571956, 23002, '<td valign="top">great shot.  but I think you are shoe horning it into the challenge.  the primary focus of this shot are the clouds and lightning/rain, not the city lights.  would have been a 9 if it met the challenge. instead it is now a 4</td>', 'great shot.  but I think you are shoe horning it into the challenge.  the primary focus of this shot are the clouds and lightning/rain, not the city lights.  would have been a 9 if it met the challenge. instead it is now a 4', '2007-08-15 01:46:05.000000', NULL, 1),
(3999098, 571853, 61818, '<td valign="top">Looks more rural, but could be an urban slum.  Either way, I really like it.</td>', 'Looks more rural, but could be an urban slum.  Either way, I really like it.', '2007-08-15 01:46:37.000000', NULL, 1),
(3999110, 570775, 23002, '<td valign="top">the flash it too harsh, and way too posed.</td>', 'the flash it too harsh, and way too posed.', '2007-08-15 01:48:38.000000', NULL, 1),
(3999111, 571479, 79720, '<td valign="top">Wonderful image. First "10" I''ve ever given.</td>', 'Wonderful image. First "10" I''ve ever given.', '2007-08-15 01:49:06.000000', NULL, 1),
(3999113, 569027, 23002, '<td valign="top">nice long exposure effect.</td>', 'nice long exposure effect.', '2007-08-15 01:49:13.000000', NULL, 1),
