(4000533, 571426, 74605, '<td valign="top">Nice sunset!  The colors reflected in the water are nice, and the silhouetted buildings add a great touch.  Nice work.</td>', 'Nice sunset!  The colors reflected in the water are nice, and the silhouetted buildings add a great touch.  Nice work.', '2007-08-15 11:49:38.000000', NULL, 1),
(4000535, 569477, 68197, '<td valign="top">Good balance of foreground water to background structures. Like the cloud reflections on the water.</td>', 'Good balance of foreground water to background structures. Like the cloud reflections on the water.', '2007-08-15 11:50:00.000000', NULL, 1),
(4000536, 571308, 74605, '<td valign="top">Nice golden tones here.  Nice perspective.</td>', 'Nice golden tones here.  Nice perspective.', '2007-08-15 11:50:09.000000', NULL, 1),
(4000538, 571030, 74605, '<td valign="top">Beautiful scene.  Welld one.</td>', 'Beautiful scene.  Welld one.', '2007-08-15 11:50:26.000000', NULL, 1),
(4000539, 570981, 68197, '<td valign="top">Sharp lines with motion blurred subject is a nice combination.</td>', 'Sharp lines with motion blurred subject is a nice combination.', '2007-08-15 11:51:20.000000', NULL, 1),
(4000540, 569913, 74605, '<td valign="top">Pretty shot.  The reflections of the building is nice.</td>', 'Pretty shot.  The reflections of the building is nice.', '2007-08-15 11:51:27.000000', NULL, 1),
(4000544, 571272, 68197, '<td valign="top">Try a slightly different composition, with the horizon line not dead center.</td>', 'Try a slightly different composition, with the horizon line not dead center.', '2007-08-15 11:52:08.000000', NULL, 1),
