(4000936, 570776, 34041, '<td valign="top">Outstanding. Could be a postcard.  My onl yissue is that is perhaps too much negative space at the bottom of the image.  croping up a bit would also better fit bby miving the horizon towards the rule of thirds, too.  Overall very good. 9 from me.</td>', 'Outstanding. Could be a postcard.  My onl yissue is that is perhaps too much negative space at the bottom of the image.  croping up a bit would also better fit bby miving the horizon towards the rule of thirds, too.  Overall very good. 9 from me.', '2007-08-15 13:31:32.000000', NULL, 1),
(4000939, 569476, 81609, '<td valign="top">beautiful shot but not relevant to the subject...urban landscape. Still beautiful.</td>', 'beautiful shot but not relevant to the subject...urban landscape. Still beautiful.', '2007-08-15 13:32:02.000000', NULL, 1),
(4000940, 568289, 34041, '<td valign="top">Humm.  I''m sure you have heard this, but not a landscape in any sense of the word.  5 for a great shot, though - just the wrong challenge to enter it into.</td>', 'Humm.  I''m sure you have heard this, but not a landscape in any sense of the word.  5 for a great shot, though - just the wrong challenge to enter it into.', '2007-08-15 13:32:17.000000', NULL, 1),
