(4000958, 570083, 34041, '<td valign="top">Oh, don''t worry. The rain will run right off the rigth hand side of the tilted roof.  :)  6 from me</td>', 'Oh, don''t worry. The rain will run right off the rigth hand side of the tilted roof.  :)  6 from me', '2007-08-15 13:34:25.000000', NULL, 1),
(4000960, 571465, 67258, '<td valign="top">de Grey''s solicitors on the corner of Blake Street and Dean Court.  I haven''t ever thought about the photographic possibilities of this building before.  Well spotted.</td>', 'de Grey''s solicitors on the corner of Blake Street and Dean Court.  I haven''t ever thought about the photographic possibilities of this building before.  Well spotted.', '2007-08-15 13:34:27.000000', NULL, 1),
(4000963, 571496, 34041, '<td valign="top">very nice. B &amp; W works well here. 7 from me.</td>', 'very nice. B & W works well here. 7 from me.', '2007-08-15 13:34:51.000000', NULL, 1),
(4000965, 570449, 81609, '<td valign="top">interesting.</td>', 'interesting.', '2007-08-15 13:35:24.000000', NULL, 1),
(4000967, 570449, 67258, '<td valign="top">Excellent observation on urban living.  My favourite of the challenge so far.</td>', 'Excellent observation on urban living.  My favourite of the challenge so far.', '2007-08-15 13:35:32.000000', NULL, 1),
(4000968, 571966, 34041, '<td valign="top">Hummm. not quite urban, at least as I define it.  I wish my urban envionment had this kind of beach in it. 6 anyway, for a good shot.</td>', 'Hummm. not quite urban, at least as I define it.  I wish my urban envionment had this kind of beach in it. 6 anyway, for a good shot.', '2007-08-15 13:35:42.000000', NULL, 1),
