(4003903, 570801, 33672, '<td valign="top">Nice duotone... However, I don''t know if this fits the description of a landscape.</td>', 'Nice duotone... However, I don''t know if this fits the description of a landscape.', '2007-08-16 10:59:16.000000', NULL, 1),
(4003904, 569357, 33672, '<td valign="top">Nice timed exposure and Perspective.</td>', 'Nice timed exposure and Perspective.', '2007-08-16 10:59:39.000000', NULL, 1),
(4003905, 572011, 33672, '<td valign="top">Buildings look a bit tilted. But I like the initial comp.</td>', 'Buildings look a bit tilted. But I like the initial comp.', '2007-08-16 11:00:11.000000', NULL, 1),
(4003907, 568215, 33672, '<td valign="top">Outstanding work. I really like the lighting.</td>', 'Outstanding work. I really like the lighting.', '2007-08-16 11:00:49.000000', NULL, 1),
(4003910, 568619, 33672, '<td valign="top">Nice shadows. The photo may have had a bit more pop and detail with the exposure turned up a stop or two...</td>', 'Nice shadows. The photo may have had a bit more pop and detail with the exposure turned up a stop or two...', '2007-08-16 11:01:54.000000', NULL, 1),
