(4004379, 569714, 60495, '<td valign="top">I like this shot, kind of gets down to how most big cities get. I was looking at a photo of another city that was taken from a distance and it was really beautiful, but everything I know about the city up close is old and dirty. Good shot</td>', 'I like this shot, kind of gets down to how most big cities get. I was looking at a photo of another city that was taken from a distance and it was really beautiful, but everything I know about the city up close is old and dirty. Good shot', '2007-08-16 13:53:41.000000', NULL, 1),
(4004385, 568339, 30049, '<td valign="top">One gallon of gas?  For a Hummer?!  Now THAT''s helpful.  :P  Fun photo with a nice glimpse of reality in the big city.  Good luck in the challenge.</td>', 'One gallon of gas?  For a Hummer?!  Now THAT''s helpful.  :P  Fun photo with a nice glimpse of reality in the big city.  Good luck in the challenge.', '2007-08-16 13:55:51.000000', NULL, 1),
(4004393, 571956, 60495, '<td valign="top">I love the layers in this shot, the clouds, the lightnig and the sky above the clouds are awesome.</td>', 'I love the layers in this shot, the clouds, the lightnig and the sky above the clouds are awesome.', '2007-08-16 14:02:07.000000', NULL, 1),
(4004560, 569476, 58691, '<td valign="top">I''m not sure if this meets the challenge of urban landscape, but I think it is a phenomenal photo. I think it could use a tad more contrast, but not much.</td>', 'I''m not sure if this meets the challenge of urban landscape, but I think it is a phenomenal photo. I think it could use a tad more contrast, but not much.', '2007-08-16 15:22:03.000000', NULL, 1),
