(4004654, 571290, 69368, '<td valign="top">Like to see all the details. good capture.</td>', 'Like to see all the details. good capture.', '2007-08-16 16:01:38.000000', NULL, 1),
(4004656, 570196, 66515, '<td valign="top">Getting better exposure on the train on the left would have really helped. The sky is muted already so let it blow out. The context of this scene is what we really need here to make this more effective.</td>', 'Getting better exposure on the train on the left would have really helped. The sky is muted already so let it blow out. The context of this scene is what we really need here to make this more effective.', '2007-08-16 16:02:20.000000', NULL, 1),
