(4006576, 571426, 33319, '<td valign="top">wow.....</td>', 'wow.....', '2007-08-17 13:00:29.000000', NULL, 1),
(4006644, 571298, 30982, '<td valign="top">This is an example to me where a "centered" composition works well, to show the path between the land and the sea.  Nicely seen.</td>', 'This is an example to me where a "centered" composition works well, to show the path between the land and the sea.  Nicely seen.', '2007-08-17 13:30:11.000000', NULL, 1),
(4006656, 570332, 30982, '<td valign="top">Lovely time of evening nicely captured.  Stonework reminds me of Germany.</td>', 'Lovely time of evening nicely captured.  Stonework reminds me of Germany.', '2007-08-17 13:31:39.000000', NULL, 1),
(4006662, 571318, 30982, '<td valign="top">Now why didn''t you move the chair over to the right?  :-)  Well seen - and I do like the tension created by the imbalance of the chair''s placement in the scene.</td>', 'Now why didn''t you move the chair over to the right?  :-)  Well seen - and I do like the tension created by the imbalance of the chair''s placement in the scene.', '2007-08-17 13:32:59.000000', NULL, 1),
(4006665, 571853, 58610, '<td valign="top">Reminds me of a Walker Evans photo. Slow shutter is interesting detail. Good tonal range.</td>', 'Reminds me of a Walker Evans photo. Slow shutter is interesting detail. Good tonal range.', '2007-08-17 13:33:29.000000', NULL, 1),
(4006672, 571017, 30982, '<td valign="top">What an elegant and civilised (with an "s" in honour of the pub part) landscape!</td>', 'What an elegant and civilised (with an "s" in honour of the pub part) landscape!', '2007-08-17 13:34:50.000000', NULL, 1),
(4006675, 569148, 30982, '<td valign="top">Very interesting design and color.</td>', 'Very interesting design and color.', '2007-08-17 13:36:00.000000', NULL, 1),
(4006678, 571104, 78303, '<td valign="top">I think this would be better as a B&amp;W shot.</td>', 'I think this would be better as a B&W shot.', '2007-08-17 13:36:07.000000', NULL, 1),
(4006681, 571879, 30982, '<td valign="top">Wonderful reflection.</td>', 'Wonderful reflection.', '2007-08-17 13:36:59.000000', NULL, 1),
(4006684, 571933, 58610, '<td valign="top">Having the picture skewed a little clockwise detracts, I think, from an otherwise succesful compostion. The dark triangle in the upper right hand corner is also distracting. Perhaps you could have set up just a bit more to your left?</td>', 'Having the picture skewed a little clockwise detracts, I think, from an otherwise succesful compostion. The dark triangle in the upper right hand corner is also distracting. Perhaps you could have set up just a bit more to your left?', '2007-08-17 13:37:47.000000', NULL, 1),
(4006686, 568289, 30982, '<td valign="top">A wonderful portrait - tender and strong.  Probably not best suited for this challenge, though.</td>', 'A wonderful portrait - tender and strong.  Probably not best suited for this challenge, though.', '2007-08-17 13:38:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
