(4012288, 571817, 2158, '<td valign="top">Great picture.  But what''s it doing in this challenge?</td>', 'Great picture.  But what''s it doing in this challenge?', '2007-08-19 23:00:30.000000', NULL, 1),
(4012294, 571853, 15204, '<td valign="top">Somehow your composition seems unbalanced to me.  Maybe that was your intent.  If the shanties are the subject, I think they need a little more room above them in the frame.  I like the line of the shanties mirrored by the muddy river, but your camera position/angle just doesn''t seem to fit quite right in the frame. I like the textures in this shot.  The ripples in the water, the grass, the wood planks on the buildings all work very well in black and white.  6 from me.</td>', 'Somehow your composition seems unbalanced to me.  Maybe that was your intent.  If the shanties are the subject, I think they need a little more room above them in the frame.  I like the line of the shanties mirrored by the muddy river, but your camera position/angle just doesn''t seem to fit quite right in the frame. I like the textures in this shot.  The ripples in the water, the grass, the wood planks on the buildings all work very well in black and white.  6 from me.', '2007-08-19 23:01:39.000000', NULL, 1),
(4012361, 571831, 61651, '<td valign="top">Cool perspective.</td>', 'Cool perspective.', '2007-08-19 23:30:06.000000', NULL, 1),
(4012369, 570981, 61651, '<td valign="top">Nice unusual take on depicting an urban landscape - something we also see everyday, and miss the beauty of it.  Good use of motion blur.</td>', 'Nice unusual take on depicting an urban landscape - something we also see everyday, and miss the beauty of it.  Good use of motion blur.', '2007-08-19 23:31:04.000000', NULL, 1),
(4012372, 571483, 61651, '<td valign="top">Dizzying - excellent location choice for wide angle.</td>', 'Dizzying - excellent location choice for wide angle.', '2007-08-19 23:31:41.000000', NULL, 1),
(4012381, 571456, 61651, '<td valign="top">Fabulous - the fact that the building vanishes into white light gives it impact and the reflections of the surrounding buildings, the contrast of architecture makes this shot very effective, to me.</td>', 'Fabulous - the fact that the building vanishes into white light gives it impact and the reflections of the surrounding buildings, the contrast of architecture makes this shot very effective, to me.', '2007-08-19 23:33:51.000000', NULL, 1),
(4012383, 570828, 61651, '<td valign="top">Very nice shot into the sun while still controlling the impact of glare in the image.  Nice study of lights and darks.</td>', 'Very nice shot into the sun while still controlling the impact of glare in the image.  Nice study of lights and darks.', '2007-08-19 23:34:51.000000', NULL, 1),
(4012386, 571398, 61651, '<td valign="top">Center comp works well here - nice framing of central subject with all that sprawl.</td>', 'Center comp works well here - nice framing of central subject with all that sprawl.', '2007-08-19 23:36:09.000000', NULL, 1),
(4012388, 569027, 61651, '<td valign="top">Excellent take on the challenge - indubitably an urban landscape.</td>', 'Excellent take on the challenge - indubitably an urban landscape.', '2007-08-19 23:36:44.000000', NULL, 1),
(4012390, 570725, 61651, '<td valign="top">Great perspective - wouldn''t have been the same without the inclusion of the commuter for a sense of scale.</td>', 'Great perspective - wouldn''t have been the same without the inclusion of the commuter for a sense of scale.', '2007-08-19 23:37:29.000000', NULL, 1),
(4012744, 571819, 33672, '<td valign="top">Great photo and PP. Interesting and original.</td>', 'Great photo and PP. Interesting and original.', '2007-08-20 01:21:07.000000', NULL, 1),
