(4013487, 571479, 83008, '<td valign="top">Very nice.. Might be just a tad too long exposure.. But a lovely capture.</td>', 'Very nice.. Might be just a tad too long exposure.. But a lovely capture.', '2007-08-20 07:57:53.000000', NULL, 1),
