(4016699, 571195, 82817, '<td valign="top">The skyscraper of mall signs. A bit of frightening chronicle of modern times in America. Great blue color in the sky.</td>', 'The skyscraper of mall signs. A bit of frightening chronicle of modern times in America. Great blue color in the sky.', '2007-08-21 06:56:30.000000', NULL, 1),
(4016703, 570196, 82817, '<td valign="top">What is the fuzzy thing in the lower right? I am drawn to this part of the photo and it is not the focus of the image.</td>', 'What is the fuzzy thing in the lower right? I am drawn to this part of the photo and it is not the focus of the image.', '2007-08-21 06:58:33.000000', NULL, 1),
(4016705, 571308, 82817, '<td valign="top">I like it.</td>', 'I like it.', '2007-08-21 06:59:26.000000', NULL, 1),
(4016709, 571326, 82817, '<td valign="top">Wish you had a wider angle lens or could back up a bit. Love the implied image.</td>', 'Wish you had a wider angle lens or could back up a bit. Love the implied image.', '2007-08-21 07:00:49.000000', NULL, 1),
(4016711, 571912, 82817, '<td valign="top">Not usually a fan of saturated colors but I think more color would help make this more dramatic. Tops of flag poles could have been included as well.</td>', 'Not usually a fan of saturated colors but I think more color would help make this more dramatic. Tops of flag poles could have been included as well.', '2007-08-21 07:03:00.000000', NULL, 1),
(4016713, 571982, 82817, '<td valign="top">Wish there was a blue sky. I''m not sure how to look at this image. Thanks.</td>', 'Wish there was a blue sky. I''m not sure how to look at this image. Thanks.', '2007-08-21 07:03:59.000000', NULL, 1),
(4016717, 571683, 82817, '<td valign="top">I love the idea but the curvature of the lens is distracting.</td>', 'I love the idea but the curvature of the lens is distracting.', '2007-08-21 07:05:38.000000', NULL, 1),
(4016720, 570725, 82817, '<td valign="top">It''s a long way to the top. I appreciate the black and white, it adds drama.</td>', 'It''s a long way to the top. I appreciate the black and white, it adds drama.', '2007-08-21 07:06:56.000000', NULL, 1),
(4016721, 569843, 82817, '<td valign="top">Dramatic.</td>', 'Dramatic.', '2007-08-21 07:07:38.000000', NULL, 1),
(4016724, 569337, 82817, '<td valign="top">What happened to the top? Love the blues.</td>', 'What happened to the top? Love the blues.', '2007-08-21 07:08:29.000000', NULL, 1),
(4016725, 571953, 82817, '<td valign="top">The leaning to the right is too much. Perspective, lens, angle? I don''t know.</td>', 'The leaning to the right is too much. Perspective, lens, angle? I don''t know.', '2007-08-21 07:09:28.000000', NULL, 1),
(4016726, 570783, 82817, '<td valign="top">My favorite so far and this is my 33rd photo. Hard to get the exposure correct for everything.</td>', 'My favorite so far and this is my 33rd photo. Hard to get the exposure correct for everything.', '2007-08-21 07:10:29.000000', NULL, 1),
(4016729, 570955, 82817, '<td valign="top">Nice angles and use of reflections.</td>', 'Nice angles and use of reflections.', '2007-08-21 07:11:55.000000', NULL, 1),
(4016733, 571200, 82817, '<td valign="top">Some of the trees are a bit dark, thus lacking detail, otherwise I like it.</td>', 'Some of the trees are a bit dark, thus lacking detail, otherwise I like it.', '2007-08-21 07:13:38.000000', NULL, 1),
(4016738, 571928, 82817, '<td valign="top">Looking East being pushed West. I never thought a building could be the serene part of an urban landscape until now.</td>', 'Looking East being pushed West. I never thought a building could be the serene part of an urban landscape until now.', '2007-08-21 07:16:05.000000', NULL, 1),
(4016740, 571138, 82817, '<td valign="top">challenging exposure. You almost got it.</td>', 'challenging exposure. You almost got it.', '2007-08-21 07:17:22.000000', NULL, 1),
(4016742, 571427, 82817, '<td valign="top">I love the streaks in the foreground. Looks a bit futuristic.</td>', 'I love the streaks in the foreground. Looks a bit futuristic.', '2007-08-21 07:18:12.000000', NULL, 1),
(4016744, 571094, 82817, '<td valign="top">I feel drunk looking at it.</td>', 'I feel drunk looking at it.', '2007-08-21 07:19:05.000000', NULL, 1),
(4016747, 569968, 82817, '<td valign="top">I don''t get an idea of your subject. Is it the white building, the beige one''s or the city in the background. Is it me or is everything tilted to the left?</td>', 'I don''t get an idea of your subject. Is it the white building, the beige one''s or the city in the background. Is it me or is everything tilted to the left?', '2007-08-21 07:21:13.000000', NULL, 1),
(4016749, 568639, 82817, '<td valign="top">The sky is lost in the clouds. I like the perspective.</td>', 'The sky is lost in the clouds. I like the perspective.', '2007-08-21 07:22:26.000000', NULL, 1),
(4016750, 570488, 82817, '<td valign="top">Very nice!</td>', 'Very nice!', '2007-08-21 07:24:02.000000', NULL, 1),
(4016751, 571106, 82817, '<td valign="top">Lights are a bit over exposed.</td>', 'Lights are a bit over exposed.', '2007-08-21 07:25:56.000000', NULL, 1),
(4016754, 571704, 82817, '<td valign="top">A tighter crop could be better.</td>', 'A tighter crop could be better.', '2007-08-21 07:27:11.000000', NULL, 1),
(4016763, 570781, 82817, '<td valign="top">Looks familiar.</td>', 'Looks familiar.', '2007-08-21 07:33:52.000000', NULL, 1),
(4016764, 571778, 82817, '<td valign="top">Urban? Nice shot though.</td>', 'Urban? Nice shot though.', '2007-08-21 07:34:36.000000', NULL, 1),
(4016765, 570173, 82817, '<td valign="top">Town-outhouses.</td>', 'Town-outhouses.', '2007-08-21 07:35:15.000000', NULL, 1),
(4016766, 571879, 82817, '<td valign="top">Love the reflection. What happened to the color, it''s very yellowish. Old postcard-like.</td>', 'Love the reflection. What happened to the color, it''s very yellowish. Old postcard-like.', '2007-08-21 07:36:47.000000', NULL, 1),
(4016771, 571917, 82817, '<td valign="top">Getty, got it, good! I love the perspective and the human and sculptural elements along with the plants.</td>', 'Getty, got it, good! I love the perspective and the human and sculptural elements along with the plants.', '2007-08-21 07:39:46.000000', NULL, 1),
(4016773, 572000, 82817, '<td valign="top">I don''t really know what it is but it works!</td>', 'I don''t really know what it is but it works!', '2007-08-21 07:40:49.000000', NULL, 1),
(4016774, 569035, 82817, '<td valign="top">Lovely light trails.</td>', 'Lovely light trails.', '2007-08-21 07:41:18.000000', NULL, 1),
(4016777, 570996, 82817, '<td valign="top">It kind of needs a blue sky and the tree in the foreground is lacking detail. A very difficult exposure, good job.</td>', 'It kind of needs a blue sky and the tree in the foreground is lacking detail. A very difficult exposure, good job.', '2007-08-21 07:43:02.000000', NULL, 1),
(4016779, 569477, 82817, '<td valign="top">Lovely reflection.</td>', 'Lovely reflection.', '2007-08-21 07:44:03.000000', NULL, 1),
(4016786, 571681, 82817, '<td valign="top">It is very interesting but a bit overexposed. Maybe saturating the colors would have helped if it is OK to do that in basic editing.</td>', 'It is very interesting but a bit overexposed. Maybe saturating the colors would have helped if it is OK to do that in basic editing.', '2007-08-21 07:46:15.000000', NULL, 1),
(4016789, 571900, 82817, '<td valign="top">Nice exposure and composition.</td>', 'Nice exposure and composition.', '2007-08-21 07:46:59.000000', NULL, 1),
(4016792, 571819, 82817, '<td valign="top">Strange pinkish cast to the foreground buildings and over exposed background. Seems like early morning.</td>', 'Strange pinkish cast to the foreground buildings and over exposed background. Seems like early morning.', '2007-08-21 07:50:00.000000', NULL, 1),
(4016794, 571398, 82817, '<td valign="top">Ironic?</td>', 'Ironic?', '2007-08-21 07:51:07.000000', NULL, 1),
(4016802, 568940, 82817, '<td valign="top">Interesting perspective. Causes one to look for more details. Like the 2 planters near the top. I almost missed them but I kept looking for a reason for the title. Thanks for the brain teaser.</td>', 'Interesting perspective. Causes one to look for more details. Like the 2 planters near the top. I almost missed them but I kept looking for a reason for the title. Thanks for the brain teaser.', '2007-08-21 07:56:01.000000', NULL, 1),
(4016803, 571985, 82817, '<td valign="top">Too much going on. But that might be your point.</td>', 'Too much going on. But that might be your point.', '2007-08-21 07:56:48.000000', NULL, 1),
(4016809, 571417, 82817, '<td valign="top">Caged in or out? A person in the window would have made the shot much more dramatic. Or at least that''s my opinion.</td>', 'Caged in or out? A person in the window would have made the shot much more dramatic. Or at least that''s my opinion.', '2007-08-21 07:59:17.000000', NULL, 1),
(4016811, 569913, 82817, '<td valign="top">Lovely painterly viewpoint.</td>', 'Lovely painterly viewpoint.', '2007-08-21 08:00:17.000000', NULL, 1),
(4016814, 571839, 82817, '<td valign="top">Looks to me like the sidewalk is the subject matter.</td>', 'Looks to me like the sidewalk is the subject matter.', '2007-08-21 08:00:57.000000', NULL, 1),
(4016815, 568215, 82817, '<td valign="top">When I lived there I never had this view of the setting sun behind the buildings. Thanks.</td>', 'When I lived there I never had this view of the setting sun behind the buildings. Thanks.', '2007-08-21 08:02:23.000000', NULL, 1),
(4016817, 570775, 82817, '<td valign="top">Works for me.</td>', 'Works for me.', '2007-08-21 08:02:55.000000', NULL, 1),
(4016820, 571739, 82817, '<td valign="top">Is the sunrise behind you? Looks washed out.</td>', 'Is the sunrise behind you? Looks washed out.', '2007-08-21 08:04:13.000000', NULL, 1),
(4016823, 569900, 82817, '<td valign="top">Love it except for the mystery light streak near the tallest building. The reflection is incredible!</td>', 'Love it except for the mystery light streak near the tallest building. The reflection is incredible!', '2007-08-21 08:06:12.000000', NULL, 1),
(4016825, 570046, 82817, '<td valign="top">I love nighttime movement shots.</td>', 'I love nighttime movement shots.', '2007-08-21 08:06:43.000000', NULL, 1),
(4016833, 568181, 82817, '<td valign="top">I love the shot but I am not sure if this meets the basic editing criteria. Are these two images put together or is this a doll house with a picture for a window. I don''t know.</td>', 'I love the shot but I am not sure if this meets the basic editing criteria. Are these two images put together or is this a doll house with a picture for a window. I don''t know.', '2007-08-21 08:11:50.000000', NULL, 1),
(4017266, 570046, 37104, '<td valign="top">Fun technique, but I don''t think it really works well here.</td>', 'Fun technique, but I don''t think it really works well here.', '2007-08-21 13:26:18.000000', NULL, 1),
(4017277, 570981, 37104, '<td valign="top">Nice composition, good contrast. Those white lines work really well. The blurriness throws it off a little.</td>', 'Nice composition, good contrast. Those white lines work really well. The blurriness throws it off a little.', '2007-08-21 13:29:32.000000', NULL, 1),
(4017280, 570226, 37104, '<td valign="top">The focus is a little off and the colors are a bit dull. Everything sort of runs together if you know what I mean.</td>', 'The focus is a little off and the colors are a bit dull. Everything sort of runs together if you know what I mean.', '2007-08-21 13:30:31.000000', NULL, 1),
(4017284, 570976, 37104, '<td valign="top">I think this would have benefitted from a tighter crop. But it''s a very nice, sharp image. Great contrast too!</td>', 'I think this would have benefitted from a tighter crop. But it''s a very nice, sharp image. Great contrast too!', '2007-08-21 13:31:30.000000', NULL, 1),
(4017287, 571956, 37104, '<td valign="top">Nice capture, especially the clouds! I don''t know how "urban" this is, but I like it nonetheless.</td>', 'Nice capture, especially the clouds! I don''t know how "urban" this is, but I like it nonetheless.', '2007-08-21 13:33:23.000000', NULL, 1),
(4017288, 568181, 61958, '<td valign="top">would have helped the straighten the vertical edge</td>', 'would have helped the straighten the vertical edge', '2007-08-21 13:33:44.000000', NULL, 1),
(4017290, 569900, 61958, '<td valign="top">well captured!</td>', 'well captured!', '2007-08-21 13:34:32.000000', NULL, 1),
(4017291, 571831, 61958, '<td valign="top">great contrast between old and new</td>', 'great contrast between old and new', '2007-08-21 13:34:55.000000', NULL, 1),
(4017292, 572000, 37104, '<td valign="top">I love the negative space up top. Contrast is really nice. I think it lacks a strong interest, whether that be texture, a subject, or shapes.</td>', 'I love the negative space up top. Contrast is really nice. I think it lacks a strong interest, whether that be texture, a subject, or shapes.', '2007-08-21 13:35:36.000000', NULL, 1),
(4017297, 571795, 37104, '<td valign="top">Interesting idea!</td>', 'Interesting idea!', '2007-08-21 13:36:25.000000', NULL, 1),
(4017300, 571816, 37104, '<td valign="top">It''s very grey and empty. That might have been your intention, but I think it just leaves the picture without interest in it.</td>', 'It''s very grey and empty. That might have been your intention, but I think it just leaves the picture without interest in it.', '2007-08-21 13:38:01.000000', NULL, 1),
(4017303, 571948, 37104, '<td valign="top">B&amp;W was a nice choice. Great symmetry.</td>', 'B&W was a nice choice. Great symmetry.', '2007-08-21 13:38:44.000000', NULL, 1),
(4017322, 569173, 80691, '<td valign="top">Nice colors and exposure.</td>', 'Nice colors and exposure.', '2007-08-21 13:42:57.000000', NULL, 1),
(4017328, 571020, 80691, '<td valign="top">Great perspective!</td>', 'Great perspective!', '2007-08-21 13:44:44.000000', NULL, 1),
(4017336, 572011, 37104, '<td valign="top">Nice colors, good angle. Well done.</td>', 'Nice colors, good angle. Well done.', '2007-08-21 13:47:49.000000', NULL, 1),
(4017338, 569984, 80691, '<td valign="top">Would like to see more of the scene.</td>', 'Would like to see more of the scene.', '2007-08-21 13:49:03.000000', NULL, 1),
(4017342, 571318, 80691, '<td valign="top">I like it. Well composed.</td>', 'I like it. Well composed.', '2007-08-21 13:49:48.000000', NULL, 1),
(4017359, 571486, 37104, '<td valign="top">Awesome colors!</td>', 'Awesome colors!', '2007-08-21 13:54:37.000000', NULL, 1),
(4017477, 571853, 82817, '<td valign="top">Very moody</td>', 'Very moody', '2007-08-21 14:33:08.000000', NULL, 1),
(4017486, 571741, 82817, '<td valign="top">Great perspective but it somehow doesn''t seem sharp. Deep blue of the sky is a nice touch as well.</td>', 'Great perspective but it somehow doesn''t seem sharp. Deep blue of the sky is a nice touch as well.', '2007-08-21 14:35:13.000000', NULL, 1),
(4017496, 571956, 82817, '<td valign="top">The storm looks powerful enough to cause urban renewal. You really captured the power of the storm and the luminescence of mother nature bearing down on the urban landscape.</td>', 'The storm looks powerful enough to cause urban renewal. You really captured the power of the storm and the luminescence of mother nature bearing down on the urban landscape.', '2007-08-21 14:38:09.000000', NULL, 1),
(4017498, 571979, 82817, '<td valign="top">Distracting plants though they do serve a purpose</td>', 'Distracting plants though they do serve a purpose', '2007-08-21 14:39:18.000000', NULL, 1),
(4017506, 571670, 82817, '<td valign="top">Looks like an urban theater set. I miss the symmetry of the chair on the far right. Cut the chair or include it, 3/4 chair, hmmmmmmmm.</td>', 'Looks like an urban theater set. I miss the symmetry of the chair on the far right. Cut the chair or include it, 3/4 chair, hmmmmmmmm.', '2007-08-21 14:42:19.000000', NULL, 1),
(4017509, 571817, 82817, '<td valign="top">Just a hint out of focus.</td>', 'Just a hint out of focus.', '2007-08-21 14:43:16.000000', NULL, 1),
(4017513, 571831, 82817, '<td valign="top">Difficult shot to get with your lens. The building at the left is tilting a bit too much.</td>', 'Difficult shot to get with your lens. The building at the left is tilting a bit too much.', '2007-08-21 14:46:14.000000', NULL, 1),
(4017516, 571361, 82817, '<td valign="top">Missing the top of the building. Could have been a bit to the left to get the other tower as well.</td>', 'Missing the top of the building. Could have been a bit to the left to get the other tower as well.', '2007-08-21 14:47:25.000000', NULL, 1),
(4017523, 569804, 82817, '<td valign="top">With blue skies, nothing but blue skies, you would have really gotten your point across. Wonderful use of perspective.</td>', 'With blue skies, nothing but blue skies, you would have really gotten your point across. Wonderful use of perspective.', '2007-08-21 14:49:59.000000', NULL, 1),
(4017529, 571290, 82817, '<td valign="top">The price of progress captured.</td>', 'The price of progress captured.', '2007-08-21 14:51:00.000000', NULL, 1),
(4017539, 571933, 82817, '<td valign="top">Love the angles and the repeating patterns especially the  triangles on the right border.</td>', 'Love the angles and the repeating patterns especially the  triangles on the right border.', '2007-08-21 14:56:28.000000', NULL, 1),
(4017547, 569138, 82817, '<td valign="top">Is this how zebra''s get there stripes? Whatever it is I like the image.</td>', 'Is this how zebra''s get there stripes? Whatever it is I like the image.', '2007-08-21 14:58:38.000000', NULL, 1),
(4017608, 568568, 45377, '<td valign="top">The cranes set amongst the mosque make an interesting subject. It looks as though the pic is tilting to the right though, would have been nice to see it straightened out. Also I think there is a little too much foreground.</td>', 'The cranes set amongst the mosque make an interesting subject. It looks as though the pic is tilting to the right though, would have been nice to see it straightened out. Also I think there is a little too much foreground.', '2007-08-21 15:24:35.000000', NULL, 1),
(4017613, 571319, 45377, '<td valign="top">Good exposure. good perspective. good effort.</td>', 'Good exposure. good perspective. good effort.', '2007-08-21 15:26:21.000000', NULL, 1),
(4017619, 568940, 45377, '<td valign="top">I like this a lot. There is something quite appealing about high-rise flats.</td>', 'I like this a lot. There is something quite appealing about high-rise flats.', '2007-08-21 15:28:34.000000', NULL, 1),
(4017626, 570979, 45377, '<td valign="top">I''m not sure about this. I think its the care I have a problem with. No car and perhaps trying the shot in B&amp;W?</td>', 'I''m not sure about this. I think its the care I have a problem with. No car and perhaps trying the shot in B&W?', '2007-08-21 15:30:35.000000', NULL, 1),
(4017631, 571773, 45377, '<td valign="top">Good shot, good composition. Shame the sky seems a bit over-exposed.</td>', 'Good shot, good composition. Shame the sky seems a bit over-exposed.', '2007-08-21 15:34:49.000000', NULL, 1),
(4017635, 569271, 45377, '<td valign="top">Good exposure. Compositionally doesn''t seem too strong. Perhaps a little too much foreground?</td>', 'Good exposure. Compositionally doesn''t seem too strong. Perhaps a little too much foreground?', '2007-08-21 15:37:18.000000', NULL, 1),
(4017640, 571290, 45377, '<td valign="top">Great subject. China? Health and safety might have something to say about the guys on the roof!</td>', 'Great subject. China? Health and safety might have something to say about the guys on the roof!', '2007-08-21 15:41:42.000000', NULL, 1),
(4017642, 569843, 45377, '<td valign="top">Good exposure. Love the sky.</td>', 'Good exposure. Love the sky.', '2007-08-21 15:42:23.000000', NULL, 1),
(4017643, 571912, 45377, '<td valign="top">Not sure about the composition. I think there is a bit too much going on in this shot. Also think its cropped a little too tight.</td>', 'Not sure about the composition. I think there is a bit too much going on in this shot. Also think its cropped a little too tight.', '2007-08-21 15:43:51.000000', NULL, 1),
(4017644, 571138, 45377, '<td valign="top">Interesting subject. Seems a touch over expsoed.</td>', 'Interesting subject. Seems a touch over expsoed.', '2007-08-21 15:44:39.000000', NULL, 1),
(4017646, 569853, 45377, '<td valign="top">Good exposure, good composition.</td>', 'Good exposure, good composition.', '2007-08-21 15:45:22.000000', NULL, 1),
(4017649, 570909, 45377, '<td valign="top">I like this, good exposure, good de-saturation. I think there is a bit too much sky, I think? Good effort.</td>', 'I like this, good exposure, good de-saturation. I think there is a bit too much sky, I think? Good effort.', '2007-08-21 15:47:34.000000', NULL, 1),
(4017650, 569943, 45377, '<td valign="top">Urban landscape? Good de-saturation.</td>', 'Urban landscape? Good de-saturation.', '2007-08-21 15:48:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4017651, 571326, 29486, '<td valign="top">Cool looking building.</td>', 'Cool looking building.', '2007-08-21 15:49:04.000000', NULL, 1),
(4017652, 571270, 75162, '<td valign="top">Great focale, and tones<br/>I love the highlighted character on the dark water :)</td>', 'Great focale, and tonesI love the highlighted character on the dark water :)', '2007-08-21 15:49:44.000000', NULL, 1),
(4017653, 571647, 29486, '<td valign="top">It''s so busy. I''m not sure what you want me to look out because nothing really stands out.</td>', 'It''s so busy. I''m not sure what you want me to look out because nothing really stands out.', '2007-08-21 15:49:56.000000', NULL, 1),
(4017654, 571683, 45377, '<td valign="top">Nice exposure. I quite like the fact that you can see the ghostly figures &amp; cars in the foreground.</td>', 'Nice exposure. I quite like the fact that you can see the ghostly figures & cars in the foreground.', '2007-08-21 15:49:59.000000', NULL, 1),
(4017655, 571823, 29486, '<td valign="top">I think you put this in the wrong challenge.</td>', 'I think you put this in the wrong challenge.', '2007-08-21 15:50:33.000000', NULL, 1),
(4017657, 571361, 45377, '<td valign="top">Not sure about the composition, also quality of the image does not look too good.</td>', 'Not sure about the composition, also quality of the image does not look too good.', '2007-08-21 15:52:21.000000', NULL, 1),
(4017658, 571030, 29486, '<td valign="top">Nice composition</td>', 'Nice composition', '2007-08-21 15:52:23.000000', NULL, 1),
(4017660, 571816, 29486, '<td valign="top">Low contrast. The title suggests despair, etc. Probably should have made this B/W and given it some feeling.</td>', 'Low contrast. The title suggests despair, etc. Probably should have made this B/W and given it some feeling.', '2007-08-21 15:53:16.000000', NULL, 1),
(4017664, 571268, 29486, '<td valign="top">Would like to see same shot at dusk. The sky would then give a nice frame to the buildings.</td>', 'Would like to see same shot at dusk. The sky would then give a nice frame to the buildings.', '2007-08-21 15:54:27.000000', NULL, 1),
(4017669, 571806, 29486, '<td valign="top">Lots of color. Fun.</td>', 'Lots of color. Fun.', '2007-08-21 15:57:34.000000', NULL, 1),
(4017673, 568181, 29486, '<td valign="top">Now there''s something you don''t see everyday. I''d hate to live across the street.</td>', 'Now there''s something you don''t see everyday. I''d hate to live across the street.', '2007-08-21 15:58:46.000000', NULL, 1),
(4017676, 570083, 29486, '<td valign="top">Needed to straighten the building. Nice swirl on the cloud but since it IS the picture, it should be much more prominent (brighter, more contrasty).</td>', 'Needed to straighten the building. Nice swirl on the cloud but since it IS the picture, it should be much more prominent (brighter, more contrasty).', '2007-08-21 16:00:09.000000', NULL, 1),
(4017682, 571273, 29486, '<td valign="top">I like the idea but having a line drawn right down the middle is bad composition unless the symettry of the photo supports it. In this photo it doesn''t.</td>', 'I like the idea but having a line drawn right down the middle is bad composition unless the symettry of the photo supports it. In this photo it doesn''t.', '2007-08-21 16:02:20.000000', NULL, 1),
