(4019317, 571479, 55330, '<td valign="top">just perfect....congrats</td>', 'just perfect....congrats', '2007-08-22 01:41:26.000000', NULL, 0),
(4019320, 569853, 5112, '<td valign="top">Pretty good, Mr. Freed :)  Congratulations on a great finish.<br/> <br/>You could aim to get all your picts on your profile page to be of this bridge.</td>', 'Pretty good, Mr. Freed :)  Congratulations on a great finish. You could aim to get all your picts on your profile page to be of this bridge.', '2007-08-22 01:42:14.000000', NULL, 0),
(4019321, 571341, 30982, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by meyers:</b></div><hr/><i> The low dust cloud and slight ridge between the town and the power grid really add to their sense of motion.  I really liked this shot.  You might have cropped the power lines on the right, and brought the left side in a bit to keep the rest balanced. </i></td></tr></table> <br/>You know, I did think about cropping the right side to get rid of the partial towers... but it was already uploaded to the site, and to change it required working on the laptop, transferring to thumbdrive, putting on the work desktop, then hoping for a good connectivity day.  Besides, I decided I liked it a bit unbalanced.  :-)</td>', 'Originally posted by meyers: The low dust cloud and slight ridge between the town and the power grid really add to their sense of motion.  I really liked this shot.  You might have cropped the power lines on the right, and brought the left side in a bit to keep the rest balanced.  You know, I did think about cropping the right side to get rid of the partial towers... but it was already uploaded to the site, and to change it required working on the laptop, transferring to thumbdrive, putting on the work desktop, then hoping for a good connectivity day.  Besides, I decided I liked it a bit unbalanced.  :-)', '2007-08-22 01:42:21.000000', NULL, 0),
(4019322, 569325, 55330, '<td valign="top">sweet lighting and natural framing</td>', 'sweet lighting and natural framing', '2007-08-22 01:43:38.000000', NULL, 0),
(4019326, 570690, 66384, '<td valign="top">Beautiful shot. I really like the gold reflection. Congratulations on your PB and a top 10 finish. I gave you an 9, and for what it''s worth, I scored this higher than the three ribbon winners.</td>', 'Beautiful shot. I really like the gold reflection. Congratulations on your PB and a top 10 finish. I gave you an 9, and for what it''s worth, I scored this higher than the three ribbon winners.', '2007-08-22 01:44:40.000000', NULL, 0),
(4019332, 569595, 35669, '<td valign="top">nice work Jayson, good score too!! :)</td>', 'nice work Jayson, good score too!! :)', '2007-08-22 01:45:45.000000', NULL, 0),
(4019356, 569943, 56880, '<td valign="top">Wow, you got robbed on this one.  Landscapes can be done in macro, like what you have here.  I gave this a 9.</td>', 'Wow, you got robbed on this one.  Landscapes can be done in macro, like what you have here.  I gave this a 9.', '2007-08-22 01:50:58.000000', NULL, 0),
