(4019403, 571318, 58728, '<td valign="top">Mmmmm.  One of my faves in the challenge.  Congrats on a nice score.  It''s beautiful.</td>', 'Mmmmm.  One of my faves in the challenge.  Congrats on a nice score.  It''s beautiful.', '2007-08-22 02:05:35.000000', NULL, 0),
