(4019413, 571670, 58728, '<td valign="top">I was hoping this would score higher than this.  It''s one of my favorites from the challenge.  Excellent.</td>', 'I was hoping this would score higher than this.  It''s one of my favorites from the challenge.  Excellent.', '2007-08-22 02:08:17.000000', NULL, 0),
(4019420, 571670, 40106, '<td valign="top">how danged cute!</td>', 'how danged cute!', '2007-08-22 02:10:06.000000', NULL, 0),
(4019425, 571199, 58728, '<td valign="top">Wow, this is so under appreciated. i had given it a 10 during voting.  I''m happy that you got a posthumous ribbon.  Well deserved.  Congrats.</td>', 'Wow, this is so under appreciated. i had given it a 10 during voting.  I''m happy that you got a posthumous ribbon.  Well deserved.  Congrats.', '2007-08-22 02:12:36.000000', NULL, 0),
(4019426, 571764, 67697, '<td valign="top">Look at you!  Great score - and nice placement!  Good photo with great composition and lighting.</td>', 'Look at you!  Great score - and nice placement!  Good photo with great composition and lighting.', '2007-08-22 02:14:28.000000', NULL, 0),
(4019432, 571427, 30982, '<td valign="top">I''m thinking a new personal best ain''t bad.  This was one of my top picks - I realize that''s no consolation, but bear in mind that probably 99% of DPC''ers never ever see a 7, so you''re up there in the stratosphere with the elite.</td>', 'I''m thinking a new personal best ain''t bad.  This was one of my top picks - I realize that''s no consolation, but bear in mind that probably 99% of DPC''ers never ever see a 7, so you''re up there in the stratosphere with the elite.', '2007-08-22 02:19:15.000000', NULL, 0),
(4019451, 571823, 42577, '<td valign="top">I entered this in the urban challenge instead of the rural one. My bad.</td>', 'I entered this in the urban challenge instead of the rural one. My bad.', '2007-08-22 02:25:41.000000', NULL, 0),
(4019503, 571486, 78356, '<td valign="top">Thanks to all that liked this image. I have the luck to live in this wonderful city.<br/> <br/>Thanks</td>', 'Thanks to all that liked this image. I have the luck to live in this wonderful city. Thanks', '2007-08-22 02:45:34.000000', NULL, 0),
(4019530, 569900, 33352, '<td valign="top">Hey Dave way to go, great photo &amp; congrates on a personal best...</td>', 'Hey Dave way to go, great photo & congrates on a personal best...', '2007-08-22 02:58:52.000000', NULL, 0),
(4019534, 571272, 78303, '<td valign="top">A clean sweep on this one.  A vote from each of the point totals!  And, from the voting period, it seemed lilke I really ticked off Nikon users more than anything.  5 out of 6 were Nikon shooters.  <br/> <br/>I really just grabbe this photo from a collection I shot from a parking garage downtown.  It doesn''t contain anything of major importance, with the possible exception of Union Station, the train station and the bridge is pretty cool.  Otherwise, what you see is the Northwest section of Portland, with construction, old buildings, new areas - basicly a city in change.  But, hardly a postcard.  <br/> <br/></td>', 'A clean sweep on this one.  A vote from each of the point totals!  And, from the voting period, it seemed lilke I really ticked off Nikon users more than anything.  5 out of 6 were Nikon shooters.   I really just grabbe this photo from a collection I shot from a parking garage downtown.  It doesn''t contain anything of major importance, with the possible exception of Union Station, the train station and the bridge is pretty cool.  Otherwise, what you see is the Northwest section of Portland, with construction, old buildings, new areas - basicly a city in change.  But, hardly a postcard.   ', '2007-08-22 03:01:31.000000', NULL, 0),
(4019536, 569325, 33352, '<td valign="top">Great Sandy, I''l sit with you on any page.</td>', 'Great Sandy, I''l sit with you on any page.', '2007-08-22 03:02:53.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4019566, 571341, 33352, '<td valign="top">Awesome reality Deb, this really does portray Urban landscape, I am surprised it did not finish higher. The towers are well photographed and dwarf the town by thier hight..well done.</td>', 'Awesome reality Deb, this really does portray Urban landscape, I am surprised it did not finish higher. The towers are well photographed and dwarf the town by thier hight..well done.', '2007-08-22 03:17:49.000000', NULL, 0),
(4019583, 568639, 69109, '<td valign="top">For me, basic editing means only curves, levels and sharpen. It would have done much better with Photomatix, highlights and shadows like several people did. Now I know. But I find some pictures really overprocessed, including ribbons. It''s not basic editing any more.</td>', 'For me, basic editing means only curves, levels and sharpen. It would have done much better with Photomatix, highlights and shadows like several people did. Now I know. But I find some pictures really overprocessed, including ribbons. It''s not basic editing any more.', '2007-08-22 03:21:50.000000', NULL, 0),
(4019609, 571270, 27181, '<td valign="top">Thank you guys for the comments!<br/> <br/>We walked to the lake here early morning to just smell the fresh air. My son, after seeing the beach, became very excited and wanted to swim. We weren''t prepared and didn''t bring and swimming gear so we just took his clothes off and let him run to the water. And I saw a good opportunity for Urban Landscapes. hehe.<br/> <br/>Cheers!!!</td>', 'Thank you guys for the comments! We walked to the lake here early morning to just smell the fresh air. My son, after seeing the beach, became very excited and wanted to swim. We weren''t prepared and didn''t bring and swimming gear so we just took his clothes off and let him run to the water. And I saw a good opportunity for Urban Landscapes. hehe. Cheers!!!', '2007-08-22 03:28:59.000000', NULL, 0),
(4019630, 571741, 80058, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by slaakso:</b></div><hr/><i> Great perspective but it somehow doesn''t seem sharp. Deep blue of the sky is a nice touch as well. </i></td></tr></table> <br/> <br/>=( I don''t why it doesnt seem sharp, I had some trouble with saving it for some reason. Might be what it is! I got a print of this shot and its not blurred!!!!!!!!!!</td>', 'Originally posted by slaakso: Great perspective but it somehow doesn''t seem sharp. Deep blue of the sky is a nice touch as well.   =( I don''t why it doesnt seem sharp, I had some trouble with saving it for some reason. Might be what it is! I got a print of this shot and its not blurred!!!!!!!!!!', '2007-08-22 03:36:05.000000', NULL, 0),
(4019631, 571741, 80058, '<td valign="top">Funniest thing is, I thought this was 1 of my best entries was quiet happy with it... *roll eyes*</td>', 'Funniest thing is, I thought this was 1 of my best entries was quiet happy with it... *roll eyes*', '2007-08-22 03:37:00.000000', NULL, 0),
(4019645, 571819, 75162, '<td valign="top">Haha!<br/>Ok my comment saying that the saturations have exploded on this image made me elligible for a wonderful PM from the author :) :) :)<br/> <br/>so let me explain myself<br/>I mean that you''ve pushed too far your lovely sat slider. If you look at the bakground buildings, the color channel is way too strong for a luminosity channel that you''ve left fairly high.<br/> <br/>Atmosphere and pollution make the far objects look uncontrasted and desaturated. If you try to reverse that, you will end up with a false-looking pic<br/> <br/>Let me apologise myself if i wasn''t clear in my first message.</td>', 'Haha!Ok my comment saying that the saturations have exploded on this image made me elligible for a wonderful PM from the author :) :) :) so let me explain myselfI mean that you''ve pushed too far your lovely sat slider. If you look at the bakground buildings, the color channel is way too strong for a luminosity channel that you''ve left fairly high. Atmosphere and pollution make the far objects look uncontrasted and desaturated. If you try to reverse that, you will end up with a false-looking pic Let me apologise myself if i wasn''t clear in my first message.', '2007-08-22 03:45:25.000000', NULL, 0),
(4019651, 569027, 80058, '<td valign="top">Way under rated!!! Most of the shots I thought was briliant in this challenge seem to have done badly!? Not even too keen on the top 3... lol</td>', 'Way under rated!!! Most of the shots I thought was briliant in this challenge seem to have done badly!? Not even too keen on the top 3... lol', '2007-08-22 03:48:40.000000', NULL, 0),
(4019653, 569943, 75162, '<td valign="top">Agreed with mayers</td>', 'Agreed with mayers', '2007-08-22 03:48:41.000000', NULL, 0),
(4019654, 571704, 3032, '<td valign="top">I do not agree with the tighter crop comments, because:<br/>a) The image looses depth<br/>b) It looks a lot better at 800 or 1000px wide, but DPC is still lagging behind with the 640 size</td>', 'I do not agree with the tighter crop comments, because:a) The image looses depthb) It looks a lot better at 800 or 1000px wide, but DPC is still lagging behind with the 640 size', '2007-08-22 03:48:42.000000', NULL, 0),
(4019663, 571427, 80058, '<td valign="top">I think this should''ve ribboned!! Well done on th place!</td>', 'I think this should''ve ribboned!! Well done on th place!', '2007-08-22 03:53:30.000000', NULL, 0),
(4019679, 571741, 80058, '<td valign="top">I will say this I''m OUTRAGED with the results for this challenge... most shots I thought was brilliant seems to have been way under rated! I gues I''m a weirdo here, I don''t just look and count on "effort", I look for a diferent view, originality, new techniques and how the photo looks overall and the feeling th photograph is trying to convey!!!!</td>', 'I will say this I''m OUTRAGED with the results for this challenge... most shots I thought was brilliant seems to have been way under rated! I gues I''m a weirdo here, I don''t just look and count on "effort", I look for a diferent view, originality, new techniques and how the photo looks overall and the feeling th photograph is trying to convey!!!!', '2007-08-22 03:57:59.000000', NULL, 0),
(4019690, 571479, 78021, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by sh0rty:</b></div><hr/><i> ...I think this one turned out nicer than the one you submitted for the other challange...so...I''ll keep my vote where it is. (maybe a first place for this one...if people do not change their minds after seeing it in the top three from the other challange?) </i></td></tr></table> <br/> <br/>I guess not too many came back to mark it down for duplication. An awsome picture...the 2 ribbons prove it! Congrats! :-)</td>', 'Originally posted by sh0rty: ...I think this one turned out nicer than the one you submitted for the other challange...so...I''ll keep my vote where it is. (maybe a first place for this one...if people do not change their minds after seeing it in the top three from the other challange?)   I guess not too many came back to mark it down for duplication. An awsome picture...the 2 ribbons prove it! Congrats! :-)', '2007-08-22 04:05:24.000000', NULL, 0),
(4019695, 570488, 49109, '<td valign="top">Congrats on your 5th, Tim (still even in ribbons, but at least you got one HM more now)! This was my favorite in the challenge...</td>', 'Congrats on your 5th, Tim (still even in ribbons, but at least you got one HM more now)! This was my favorite in the challenge...', '2007-08-22 04:07:20.000000', NULL, 0),
(4019699, 569943, 70607, '<td valign="top">I can''t believe that this photo wasn''t placed much higher, I love this shot.  Skylines are beautiful no doubt (and there certainly has been some outstanding ones in this challenge) but a bit of originality should never be dismissed........in my (humble) opinion.</td>', 'I can''t believe that this photo wasn''t placed much higher, I love this shot.  Skylines are beautiful no doubt (and there certainly has been some outstanding ones in this challenge) but a bit of originality should never be dismissed........in my (humble) opinion.', '2007-08-22 04:08:39.000000', NULL, 0),
(4019742, 571486, 52549, '<td valign="top">This is so beautiful, it looks like a painting. Excellent, really excellent. Congratulations on 2nd place.</td>', 'This is so beautiful, it looks like a painting. Excellent, really excellent. Congratulations on 2nd place.', '2007-08-22 04:31:56.000000', NULL, 0),
(4019781, 569325, 34462, '<td valign="top">Good photo Sandy. I love the River Walk and all of the activity. Maybe it''s time to plan a trip to San Antonio. I''ll be sure to go early...</td>', 'Good photo Sandy. I love the River Walk and all of the activity. Maybe it''s time to plan a trip to San Antonio. I''ll be sure to go early...', '2007-08-22 05:27:03.000000', NULL, 0),
