INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4377792, 570362, 85886, '<td valign="top">Great photograph.  As I''m learning, anything too challenging will freak out the voters - but as an artistic endeavour yours kicks ass.  It is challenging because of the sheer scale of the negative space but that''s what makes it a great photograph.  I think some people like being challenged whereas others don''t (i.e. some enjoy that discomfort and questioning - I know I do).<br/> <br/>If this image was on a large canvas or a large framed print I could see this going for big money...especially because of the natural tones, making it easy to use in interior design.  For me it''s a very artistic image and the square crop is perfect for the symmetry.  Very Zen....imagine this in a stockbrokers penthouse suite....think £2k.... ;)<br/><br/><i>Message edited by author 2008-01-09 12:55:52.</i></td>', 'Great photograph.  As I''m learning, anything too challenging will freak out the voters - but as an artistic endeavour yours kicks ass.  It is challenging because of the sheer scale of the negative space but that''s what makes it a great photograph.  I think some people like being challenged whereas others don''t (i.e. some enjoy that discomfort and questioning - I know I do). If this image was on a large canvas or a large framed print I could see this going for big money...especially because of the natural tones, making it easy to use in interior design.  For me it''s a very artistic image and the square crop is perfect for the symmetry.  Very Zen....imagine this in a stockbrokers penthouse suite....think £2k.... ;)', '2008-01-09 12:52:47.000000', '2008-01-09 12:55:52.000000', 0),
(4399747, 570173, 85097, '<td valign="top">Who knew toilets could be so interesting?  great use of DOF.  really like it</td>', 'Who knew toilets could be so interesting?  great use of DOF.  really like it', '2008-01-17 11:29:37.000000', NULL, 0),
